 * ==========================================================================
 * Ohne Datenbank ladbar (reine Funktionen); DB nur in ch_i18n_bootstrap() / ch_conv_lang_* / ch_agent_langs_save().
 * Codes und Namen wie ASSISTANT_LANG_TABLE (assistant-lib.php): 'no' = Norwegisch (Bokmål, BCP-47 nb-NO).
 *
 *   ch_lang_norm($x)                  'nb-NO' → 'no', 'en_US' → 'en', unbekannt → ''
 *   ch_lang_name($l,'en'|'native'|'de')
 *   ch_detect_lang($text,$fallback,&$sure)   Erkennung je Nachricht: Schrift (JA, RU), dann Wörter + Sonderzeichen (TR/AZ/FI/SV/NO/NL/IT/ES/FR/DE/EN)
 *   ch_lang_named($text)              ausdrücklich gewählte Sprache („English please“, „auf Türkisch“, „日本語で“) → Code
 *   ch_cfg_default($cfg) / ch_cfg_langs($cfg)   Standardsprache (agent_configs.lang) + erlaubte Sprachen (agent_configs.langs, CSV; leer = alle 13)
 *   ch_reply_lang($cfg,$text,$prev,$hint)      Antwortsprache eines Gesprächs (erkannt → bisherige → Hinweis → Standard), nur erlaubte Sprachen
 *   ch_lang_directive($lang,$cfg,$detected)    Systemprompt-Baustein mit englischem + eigenem Sprachnamen und Formatbeispielen
 *   ch_fmt_money / ch_fmt_date / ch_fmt_time / ch_fmt_clock   Preise, Daten, Uhrzeiten je Sprache (ohne intl-Erweiterung)
 *   ch_conv_lang_get/set              Gesprächssprache je Kontakt (Tabelle ch_conv_lang: Konto, Kanal, Absender/Anruf)
 *   t($key,$lang,$vars) / ch_t        Wörterbuch der Kundenseiten (book, order, ride, stay, callback) + feste Kanaltexte
 *   ch_page_lang($allowed,$default)   ?lang= → Cookie ch_lang → Accept-Language → Cloudflare CF-IPCountry → Standard
 *   ch_lang_switcher($cur,$allowed)   kompakte Sprachauswahl (Links, ohne JavaScript, Touch-Ziele ≥ 44 px)
 */

