/** native = Eigenname, en = englischer Name (Prompt, Sprechanweisung), de = Name in der deutschen Oberfläche, tag = BCP-47 der Oberfläche,
 *  phone = Twilio-Locale für <Say>/<Gather> (az: Erkennung az-AZ, Stimme tr-TR – Twilio hat keine aserbaidschanische Stimme). */
