function ch_lang_norm($l): string {
    if(!is_string($l)) return '';
    $l=strtolower(trim(str_replace('_','-',$l))); if($l==='') return '';
    if(preg_match('/^(nb|nn|no)(-|$)/',$l)) return 'no';
    $p=substr($l,0,2);
    return in_array($p,CH_LANG_CODES,true) ? $p : '';
}
function ch_lang_name(string $l, string $form='en'): string { $l=ch_lang_norm($l) ?: 'de'; return CH_LANGS[$l][$form] ?? CH_LANGS[$l]['en']; }
function ch_lang_tag(string $l): string { return CH_LANGS[ch_lang_norm($l) ?: 'de']['tag']; }

