/** Punktzahlen je Sprache (für Tests und Feinabstimmung). Schrift: ja/ru erhalten 100. */
function ch_detect_lang_scores(string $t): array {
    $sc=array_fill_keys(CH_LANG_CODES,0.0);
    $kana=preg_match_all('/[\p{Hiragana}\p{Katakana}]/u',$t); $han=preg_match_all('/\p{Han}/u',$t); $cyr=preg_match_all('/\p{Cyrillic}/u',$t);
    $lat=preg_match_all('/[a-zA-Z\x{00C0}-\x{024F}\x{0259}]/u',$t);
    if($kana>=1 || ($han>=2 && $cyr===0)){ $sc['ja']=100.0; return $sc; }
    if($cyr>=2 && $cyr>=$lat){ $sc['ru']=100.0; return $sc; }
    $low=mb_strtolower($t,'UTF-8'); $low=str_replace(['’','`'],'\'',$low);
    $tok=preg_split('/[^\p{L}\']+/u',$low,-1,PREG_SPLIT_NO_EMPTY) ?: [];
    $tok=array_map(fn($w)=>trim($w,'\''),$tok);
    foreach(CH_DETECT_WORDS as $l=>$ws){ static $sets=[]; $sets[$l]??=array_flip($ws); foreach($tok as $w) if(isset($sets[$l][$w])) $sc[$l]+=1; }
    $n=fn(string $re)=>preg_match_all($re,$low);
    $sc['az']+=3*min(3,$n('/ə/u'));
    $dotless=$n('/[ığş]/u'); $sc['tr']+=1.5*min(3,$dotless); $sc['az']+=1.0*min(3,$dotless);
    $sc['de']+=2*$n('/ß/u'); $u=min(2,$n('/ü/u')); $sc['de']+=0.5*$u; $sc['tr']+=0.5*$u; $sc['az']+=0.5*$u;
    $o=min(2,$n('/ö/u')); foreach(['de','tr','az','sv','fi'] as $l) $sc[$l]+=0.4*$o;
    $a=min(3,$n('/ä/u')); $sc['de']+=0.4*$a; $sc['sv']+=0.4*$a; $sc['fi']+=0.8*$a;
    $sc['sv']+=min(2,$n('/å/u')); $sc['no']+=min(2,$n('/å/u')); $sc['no']+=2*min(2,$n('/[æø]/u'));
    $sc['es']+=2*min(2,$n('/[ñ¿¡]/u')); $sc['es']+=0.5*min(2,$n('/[áíóú]/u'));
    $sc['it']+=0.5*min(2,$n('/[òùì]/u'));
    $c=min(2,$n('/ç/u')); $sc['fr']+=0.8*$c; $sc['tr']+=0.6*$c; $sc['az']+=0.6*$c;
    $sc['fr']+=2*min(1,$n('/œ/u')); $sc['fr']+=0.5*min(2,$n('/[êâîôûëï]/u')); $sc['fr']+=0.4*min(2,$n('/[éè]/u'));
    $sc['nl']+=0.5*min(2,$n('/ij/u'));
    $dv=0; foreach($tok as $w) $dv+=preg_match_all('/(aa|ee|ii|uu|yy|ää|öö)/u',$w); $sc['fi']+=0.5*min(4,$dv);
    $sc['az']+=0.8*min(2,$n('/\p{L}*(q|x)\p{L}*[ıəüö]|[ıəüö]\p{L}*(q|x)/u'));   // q/x neben türkischen Vokalen: aserbaidschanisch
    return $sc;
}
/** Sprache eines Kundentextes. $sure=false → $fallback (unsicher: zu kurz, Gleichstand, nur mehrdeutige Wörter). */
function ch_detect_lang(string $t, string $fallback='', ?bool &$sure=null): string {
    $sure=false; $t=trim($t); if($t==='') return $fallback;
    $sc=ch_detect_lang_scores(mb_substr($t,0,600));
    arsort($sc); $k=array_keys($sc); $best=$k[0]; $top=$sc[$best]; $second=$sc[$k[1]];
    if($top>=1 && $top-$second>=1){ $sure=true; return $best; }
    return $fallback;
}
