/** Ausdrücklich gewählte Sprache in einer kurzen Äußerung („English, please“, „auf Türkisch bitte“, „日本語でお願いします“) → Code, sonst ''. */
function ch_lang_named(string $t): string {
    $low=mb_strtolower(trim($t),'UTF-8'); if($low==='') return '';
    $words=preg_split('/[^\p{L}\-]+/u',$low,-1,PREG_SPLIT_NO_EMPTY) ?: [];
    $cjk=preg_match('/\p{Han}|\p{Hiragana}|\p{Katakana}/u',$low)===1;
    if(count($words)>6 && !$cjk) return '';
    $hit=[];
    foreach(CH_LANG_SPOKEN as $code=>$names) foreach($names as $n){
        if(preg_match('/\p{Han}|\p{Hiragana}|\p{Katakana}/u',$n) ? mb_strpos($low,$n)!==false : in_array($n,$words,true)){ $hit[$code]=1; break; }
    }
    return count($hit)===1 ? (string)array_key_first($hit) : '';
}

/* ======================================================================= Betriebseinstellungen */
function ch_cfg_default(array $cfg): string { return ch_lang_norm((string)($cfg['lang'] ?? '')) ?: 'de'; }
/** Erlaubte Sprachen (Standardsprache zuerst). agent_configs.langs = CSV, leer = alle 13. */
function ch_cfg_langs(array $cfg): array {
    $def=ch_cfg_default($cfg); $raw=trim((string)($cfg['langs'] ?? ''));
    $l=$raw==='' ? CH_LANG_CODES : array_values(array_filter(array_map('ch_lang_norm',preg_split('/[\s,;]+/',$raw) ?: [])));
    return array_values(array_unique(array_merge([$def],$l)));
}
/** Antwortsprache: sicher erkannt (und erlaubt) → diese; unsicher → bisherige Gesprächssprache → Hinweis (Browser/Seite) → Standard. */
function ch_reply_lang(array $cfg, string $text, string $prev='', string $hint='', ?bool &$sure=null): string {
    $allowed=ch_cfg_langs($cfg); $def=ch_cfg_default($cfg);
    $named=ch_lang_named($text); $d=$named!=='' ? $named : ch_detect_lang($text,'',$sure); if($named!=='') $sure=true;
    if($sure) return in_array($d,$allowed,true) ? $d : $def;
    foreach([ch_lang_norm($prev),ch_lang_norm($hint)] as $x) if($x!=='' && in_array($x,$allowed,true)) return $x;
    return $def;
}
/** Systemprompt-Baustein Sprache. $detected=true: $lang ist die (erkannte) Sprache des Kunden; false: nur Standardsprache bekannt. */
function ch_lang_directive(string $lang, array $cfg=[], bool $detected=true): string {
    $def=ch_cfg_default($cfg); $l=$detected ? (ch_lang_norm($lang) ?: $def) : $def; $allowed=ch_cfg_langs($cfg);
    $nm=fn(string $c)=>CH_LANGS[$c]['en'].' ('.CH_LANGS[$c]['native'].')';
    $all=count($allowed)>=count(CH_LANG_CODES);
    $offer=$all ? '' : ' Dieser Betrieb bedient nur: '.implode(', ',array_map(fn($c)=>CH_LANGS[$c]['en'],$allowed)).'; schreibt jemand in einer anderen Sprache, antworte höflich auf '.CH_LANGS[$def]['en'].' und sag kurz, in welchen Sprachen du helfen kannst.';
    $dt=new DateTimeImmutable('2026-10-22 15:30:00',new DateTimeZone('Europe/Berlin'));   // Donnerstag – nur Formatbeispiel
    $fmt=' Formate auf '.CH_LANGS[$l]['en'].': Datum wie „'.ch_fmt_date($dt,$l,'day').'“, Uhrzeit wie „'.ch_fmt_clock('15:30',$l).'“, Preise wie „'.ch_fmt_money(1250,$l).'“ – Daten, Zeiten und Preise aus Werkzeug-Ergebnissen in dieses Format umschreiben (Codes, Namen, Adressen und Telefonnummern unverändert lassen).';
    $style=CH_LANG_STYLE[$l] ?? '';
    if($detected){
        $s=' SPRACHE: Antworte auf '.$nm($l).' – das ist die Sprache des Kunden. Wissensbasis, Werkzeug-Ergebnisse und diese Anweisungen sind oft deutsch: übersetze die Inhalte natürlich, antworte aber nie auf Deutsch, solange der Kunde '.CH_LANGS[$l]['en'].' schreibt oder spricht.'
          .' Wechselt der Kunde erkennbar die Sprache, wechsle mit ihm.';
        if($l==='de') $s=' SPRACHE: Antworte auf '.$nm('de').'. Wechselt der Kunde erkennbar in eine andere Sprache, antworte in seiner Sprache.';
    } else {
        $s=' SPRACHE: Standardsprache ist '.$nm($def).'. Schreibt oder spricht der Kunde erkennbar eine andere Sprache, antworte in dessen Sprache.';
    }
    return $s.$offer.$fmt.($style!=='' ? ' '.$style : '');
}
