function ch_fmt_num(float $v, int $dec, string $lang): string { $f=CH_LANG_FMT[ch_lang_norm($lang) ?: 'de']['num']; return number_format($v,$dec,$f[0],$f[1]==' ' ? "\u{202F}" : $f[1]); }
/** Betrag in Cent → „12,50 €“ / „€12.50“ / „€ 12,50“ … (ganze Beträge ohne Nachkommastellen nur, wenn $trim). */
function ch_fmt_money(int $cents, string $lang, string $cur='EUR', bool $trim=false): string {
    $l=ch_lang_norm($lang) ?: 'de'; $n=ch_fmt_num(abs($cents)/100,($trim && $cents%100===0) ? 0 : 2,$l);
    $s=str_replace('{n}',$n,CH_LANG_FMT[$l]['cur']); if($cur!=='EUR') $s=str_replace('€',$cur,$s);
    return ($cents<0 ? '−' : '').$s;
}
/** Datum: long „Donnerstag, 22. Oktober 2026“ · day „Donnerstag, 22. Oktober“ · short „Do, 22.10.“ · dm „22.10.“ */
function ch_fmt_date(DateTimeInterface $d, string $lang, string $style='long'): string {
    $l=ch_lang_norm($lang) ?: 'de'; $F=CH_LANG_FMT[$l]; $w=(int)$d->format('w'); $m=(int)$d->format('n');
    $p=$F[$style] ?? $F['long'];
    return strtr($p,['{W}'=>$F['W'][$w],'{w}'=>$F['w'][$w],'{d}'=>$d->format('j'),'{M}'=>$F['M'][$m-1],'{Ms}'=>mb_substr($F['M'][$m-1],0,3),'{m}'=>$d->format('m'),'{n}'=>(string)$m,'{Y}'=>$d->format('Y')]);
}
function ch_fmt_wd(DateTimeInterface $d, string $lang, bool $long=false): string { $F=CH_LANG_FMT[ch_lang_norm($lang) ?: 'de']; return $F[$long ? 'W' : 'w'][(int)$d->format('w')]; }
/** Uhrzeit „15:30“ (24 h in allen 13 Sprachen). */
function ch_fmt_time(DateTimeInterface $d, string $lang=''): string { return $d->format('H:i'); }
/** Uhrzeit im Satz: Deutsch „15:30 Uhr“, sonst „15:30“. */
function ch_fmt_clock(string $hm, string $lang): string { return t('clock',$lang,['t'=>$hm]); }
/** Relativer Tag + Uhrzeit: „heute um 15:30“, „morgen (Fr, 23.10.) um 15:30“, „Mo, 26.10. um 15:30“. */
function ch_fmt_when(DateTimeImmutable $at, DateTimeImmutable $now, string $lang): string {
    $days=(int)$now->setTime(0,0)->diff($at->setTimezone($now->getTimezone())->setTime(0,0))->format('%r%a'); $tm=$at->format('H:i');
    if($days===0) return t('when.today',$lang,['time'=>$tm]);
    if($days===1) return t('when.tomorrow',$lang,['time'=>$tm,'date'=>ch_fmt_date($at,$lang,'short')]);
    return t('when.at',$lang,['time'=>$tm,'date'=>ch_fmt_date($at,$lang,'short')]);
}
/** Kurze deutsche Bausteine aus Fachbibliotheken (Wochentags-Kürzel, „Uhr“, „heute“ …) in die Seitensprache übertragen. */
function ch_de_phrase(string $s, string $lang): string {
    $l=ch_lang_norm($lang) ?: 'de'; if($l==='de' || $s==='') return $s;
    $W=CH_LANG_FMT['de']['w']; $map=[];
    foreach($W as $i=>$x) $map[$x]=CH_LANG_FMT[$l]['w'][$i];
    $s=preg_replace_callback('/(*UCP)\b(So|Mo|Di|Mi|Do|Fr|Sa)\b/u',fn($m)=>$map[$m[1]],$s) ?? $s;
    $s=preg_replace('/(*UCP)(\d)\s*Uhr\b/u','$1',$s) ?? $s;
    $s=preg_replace_callback('/(*UCP)\b(keine Anrufzeiten hinterlegt|keine Rückrufe|übermorgen|heute|morgen|sofort)\b|\bca\.(?=\s)/iu',function($m) use($l){
        $k=mb_strtolower($m[1] ?? '','UTF-8'); if($k==='') $k='ca.';
        $v=['keine anrufzeiten hinterlegt'=>t('cb.nohours',$l),'keine rückrufe'=>t('cb.noday',$l),'übermorgen'=>t('dayafter',$l),'heute'=>t('today',$l),'morgen'=>t('tomorrow',$l),'sofort'=>t('r.now',$l),'ca.'=>t('approx',$l)][$k] ?? $m[0];
        return preg_match('/^\p{Lu}/u',$m[0]) ? mb_strtoupper(mb_substr($v,0,1)).mb_substr($v,1) : $v;
    },$s) ?? $s;
    return $s;
}
/** Zahl + Einheit mit Plural: ch_tn(3,'night1','nights','ru') → „3 ночи“ (Russisch mit drei Formen: …1 / …2–4 / sonst). */
function ch_tn(int $n, string $one, string $many, string $lang): string {
    $l=ch_lang_norm($lang) ?: 'de';
    if($l==='ru'){ $a=$n%10; $b=$n%100;
        if($a===1 && $b!==11) return $n===1 ? t($one,$l,['n'=>$n]) : t($many.'1',$l,['n'=>$n]);
        if($a>=2 && $a<=4 && ($b<12 || $b>14)) return t($many.'2',$l,['n'=>$n]);
        return t($many,$l,['n'=>$n]); }
    return $n===1 ? t($one,$l,['n'=>$n]) : t($many,$l,['n'=>$n]);
}

/* ======================================================================= Datenbank (Gesprächssprache, Einstellungen) */
/** Spalte agent_configs.langs (erlaubte Sprachen, CSV) + Tabelle ch_conv_lang. Einmal je Request; Fehler brechen nie ab. */
function ch_i18n_bootstrap(): void {
    static $done=false; if($done || !function_exists('th_db')) return; $done=true;
    try{
        $p=th_db();
        $cols=$p->query("SHOW COLUMNS FROM agent_configs")->fetchAll(PDO::FETCH_COLUMN);
        if(!in_array('langs',$cols,true)) $p->exec("ALTER TABLE agent_configs ADD COLUMN langs VARCHAR(120) DEFAULT ''");
        $p->exec("CREATE TABLE IF NOT EXISTS ch_conv_lang (account_id INT NOT NULL, channel VARCHAR(16) NOT NULL, peer VARCHAR(64) NOT NULL, lang VARCHAR(8) NOT NULL DEFAULT '',
            probes TINYINT NOT NULL DEFAULT 0, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(account_id,channel,peer), INDEX(updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        if(random_int(1,200)===1) $p->exec("DELETE FROM ch_conv_lang WHERE (channel='call' AND updated_at < (NOW() - INTERVAL 2 DAY)) OR updated_at < (NOW() - INTERVAL 365 DAY)");
    }catch(Throwable $e){ error_log('CH i18n bootstrap: '.$e->getMessage()); }
}
/** ['lang'=>…,'probes'=>n] oder null. channel: wa | widget | phone (Rufnummer) | call (CallSid). */
function ch_conv_lang_get(int $acc, string $channel, string $peer): ?array {
    if($peer==='') return null; ch_i18n_bootstrap();
    try{ $s=th_db()->prepare("SELECT lang,probes FROM ch_conv_lang WHERE account_id=? AND channel=? AND peer=?"); $s->execute([$acc,$channel,mb_substr($peer,0,64)]); $r=$s->fetch(PDO::FETCH_ASSOC); }catch(Throwable $e){ return null; }
    return $r ? ['lang'=>(string)$r['lang'],'probes'=>(int)$r['probes']] : null;
}
function ch_conv_lang_set(int $acc, string $channel, string $peer, string $lang, ?int $probes=null): void {
    if($peer==='') return; ch_i18n_bootstrap(); $lang=ch_lang_norm($lang);
    try{ th_db()->prepare("INSERT INTO ch_conv_lang(account_id,channel,peer,lang,probes) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE lang=VALUES(lang),".($probes===null ? '' : 'probes=VALUES(probes),')."updated_at=NOW()")
        ->execute([$acc,$channel,mb_substr($peer,0,64),$lang,(int)$probes]); }catch(Throwable $e){ error_log('CH i18n conv set: '.$e->getMessage()); }
}
function ch_conv_lang_del(int $acc, string $channel, string $peer): void {
    try{ th_db()->prepare("DELETE FROM ch_conv_lang WHERE account_id=? AND channel=? AND peer=?")->execute([$acc,$channel,mb_substr($peer,0,64)]); }catch(Throwable $e){}
}
/** Standardsprache + erlaubte Sprachen eines Agenten speichern (Studio/API). Gibt die gespeicherte Liste zurück oder null (unbekannter Agent). */
function ch_agent_langs_save(int $acc, string $plan, string $default, array $allowed): ?array {
    ch_i18n_bootstrap(); $def=ch_lang_norm($default) ?: 'de';
    $l=array_values(array_unique(array_filter(array_map('ch_lang_norm',$allowed)))); if(!in_array($def,$l,true)) array_unshift($l,$def);
    $csv=count($l)>=count(CH_LANG_CODES) ? '' : implode(',',$l);
    $s=th_db()->prepare("UPDATE agent_configs SET lang=?, langs=? WHERE account_id=? AND plan=?"); $s->execute([$def,$csv,$acc,$plan]);
    $c=th_db()->prepare("SELECT COUNT(*) FROM agent_configs WHERE account_id=? AND plan=?"); $c->execute([$acc,$plan]);
    return (int)$c->fetchColumn()>0 ? $l : null;
}
/** Sprachvorgaben eines Kontos für Kundenseiten: Standard + erlaubte Sprachen (Vereinigung aller Agenten; ohne Agent: alle, Deutsch). */
function ch_account_langs(int $acc): array {
    if($acc<=0 || !function_exists('th_db')) return ['de',CH_LANG_CODES];
    ch_i18n_bootstrap();
    try{ $s=th_db()->prepare("SELECT lang,langs FROM agent_configs WHERE account_id=? ORDER BY updated_at DESC"); $s->execute([$acc]); $rows=$s->fetchAll(PDO::FETCH_ASSOC); }catch(Throwable $e){ $rows=[]; }
    if(!$rows) return ['de',CH_LANG_CODES];
    $def=ch_cfg_default($rows[0]); $all=[];
    foreach($rows as $r) $all=array_merge($all,ch_cfg_langs($r));
    $all=array_values(array_unique(array_merge([$def],$all)));
    return [$def,$all];
}

