const CH_COUNTRY_LANG = ['DE'=>'de','AT'=>'de','CH'=>'de','LI'=>'de','LU'=>'de','GB'=>'en','US'=>'en','IE'=>'en','AU'=>'en','CA'=>'en','NZ'=>'en','MT'=>'en','IN'=>'en',
  'FR'=>'fr','MC'=>'fr','BE'=>'fr','SN'=>'fr','MA'=>'fr','TN'=>'fr','DZ'=>'fr','ES'=>'es','MX'=>'es','AR'=>'es','CO'=>'es','CL'=>'es','PE'=>'es','VE'=>'es','EC'=>'es','UY'=>'es',
  'TR'=>'tr','CY'=>'tr','RU'=>'ru','BY'=>'ru','KZ'=>'ru','KG'=>'ru','IT'=>'it','SM'=>'it','VA'=>'it','NL'=>'nl','SR'=>'nl','SE'=>'sv','NO'=>'no','FI'=>'fi','AX'=>'sv','JP'=>'ja','AZ'=>'az'];
/** Seitensprache: ?lang= (merkt sich als Cookie ch_lang) → Cookie → Accept-Language → CF-IPCountry → $default. $allowed leer = alle 13. */
function ch_page_lang(array $allowed=[], string $default='de'): string {
    $allowed=$allowed ? array_values(array_filter(array_map('ch_lang_norm',$allowed))) : CH_LANG_CODES; $default=ch_lang_norm($default) ?: 'de';
    if(!in_array($default,$allowed,true)) $allowed[]=$default;
    $ok=fn(string $l)=>$l!=='' && in_array($l,$allowed,true);
    $q=ch_lang_norm(is_string($_GET['lang'] ?? null) ? $_GET['lang'] : '');
    if($ok($q)){ if(!headers_sent() && PHP_SAPI!=='cli') header('Set-Cookie: ch_lang='.$q.'; Path=/; Max-Age=31536000; Secure; SameSite=Lax',false); $_COOKIE['ch_lang']=$q; return $q; }
    $c=ch_lang_norm(is_string($_COOKIE['ch_lang'] ?? null) ? $_COOKIE['ch_lang'] : ''); if($ok($c)) return $c;
    $al=(string)($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '');
    if($al!==''){ $cand=[];
        foreach(explode(',',$al) as $i=>$part){ $bits=explode(';',trim($part)); $qv=1.0; foreach(array_slice($bits,1) as $b) if(preg_match('/^\s*q=([0-9.]+)/',$b,$m)) $qv=(float)$m[1]; $cand[]=[$qv,-$i,ch_lang_norm($bits[0])]; }
        rsort($cand); foreach($cand as [$qv,,$l]) if($qv>0 && $ok($l)) return $l; }
    $cc=strtoupper(substr((string)($_SERVER['HTTP_CF_IPCOUNTRY'] ?? ''),0,2)); if(isset(CH_COUNTRY_LANG[$cc]) && $ok(CH_COUNTRY_LANG[$cc])) return CH_COUNTRY_LANG[$cc];
    return $default;
}
/** Kompakte Sprachauswahl (oben rechts): <details> mit Links auf dieselbe Seite + ?lang=. Ohne JavaScript, Tastatur- und Screenreader-tauglich. */
function ch_lang_switcher(string $cur, array $allowed=[]): string {
    $cur=ch_lang_norm($cur) ?: 'de'; $langs=$allowed ? array_values(array_filter(array_map('ch_lang_norm',$allowed))) : CH_LANG_CODES; if(count($langs)<2) return '';
    $q=$_GET; unset($q['lang'],$q['_'],$q['x'],$q['e'],$q['v']); $path=strtok((string)($_SERVER['REQUEST_URI'] ?? ''),'?') ?: '';
    $h=fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');
    $o='<style>.chlsbar{display:flex;justify-content:flex-end;max-width:680px;margin:0 auto;padding:10px 16px 0}.chlsbar+.w{margin-top:8px !important}.chls{position:relative;z-index:30;font:600 13px/1 Inter,system-ui,sans-serif}.chls summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 14px;border-radius:999px;background:#fff;border:1px solid #d6d9e4;color:#0f1222;box-shadow:0 2px 8px rgba(15,18,34,.06)}'
      .'.chls summary::-webkit-details-marker{display:none}.chls summary:focus-visible,.chls a:focus-visible{outline:3px solid #b8862b;outline-offset:2px}.chls ul{position:absolute;right:0;top:50px;margin:0;padding:6px;list-style:none;background:#fff;border:1px solid #d6d9e4;border-radius:14px;box-shadow:0 12px 30px rgba(15,18,34,.14);width:max-content;max-width:calc(100vw - 24px);max-height:min(70vh,560px);overflow:auto}'
      .'.chls a{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:44px;padding:0 12px;border-radius:10px;color:#0f1222;text-decoration:none;font-weight:500}.chls a:hover{background:#f6f7fb}.chls a[aria-current]{background:#f6ecd3;font-weight:700}.chls small{color:#6b7083;font-weight:600;letter-spacing:.04em}'
      .'</style>';
    $o.='<nav class="chlsbar" aria-label="'.$h(t('lang',$cur)).'"><details class="chls"><summary aria-label="'.$h(t('lang',$cur)).': '.$h(CH_LANGS[$cur]['native']).'"><span aria-hidden="true">🌐</span> '.$h(strtoupper($cur==='no' ? 'no' : $cur)).' <span aria-hidden="true">▾</span></summary><ul role="list">';
    foreach($langs as $l){ $qq=$q; $qq['lang']=$l;
        $o.='<li><a href="'.$h($path.'?'.http_build_query($qq)).'" lang="'.$h(CH_LANGS[$l]['tag']).'" hreflang="'.$h(CH_LANGS[$l]['tag']).'"'.($l===$cur ? ' aria-current="true"' : '').'>'.$h(CH_LANGS[$l]['native']).'<small>'.$h(strtoupper($l)).'</small></a></li>'; }
    return $o.'</ul></details></nav>';
}

/** Wörterbuch: Text in $lang, sonst Englisch, sonst Deutsch, sonst der Schlüssel. {name}-Platzhalter aus $vars. */
function ch_t(string $key, string $lang='de', array $vars=[]) {
    $l=ch_lang_norm($lang) ?: 'de';
    $v=CH_I18N[$l][$key] ?? ($l!=='de' ? (CH_I18N['en'][$key] ?? null) : null) ?? CH_I18N['de'][$key] ?? $key;
    if(is_array($v)) return $v;
    if($vars){ $r=[]; foreach($vars as $k=>$x) $r['{'.$k.'}']=(string)$x; $v=strtr($v,$r); }
    return $v;
}
if(!function_exists('t')){ function t(string $key, string $lang='de', array $vars=[]) { return ch_t($key,$lang,$vars); } }
/** Mehrere Schlüssel (Präfix) als Array für JavaScript. */
function ch_t_prefix(string $prefix, string $lang): array {
    $o=[]; foreach(array_keys(CH_I18N['de']) as $k) if(str_starts_with($k,$prefix)) $o[substr($k,strlen($prefix))]=ch_t($k,$lang); return $o;
}

